INSERT INTO `category_translations` (`id`, `category_id`, `locale`, `name`, `description`) VALUES (1, 1, 'en', 'Wall-Hung Toilets', 'Premium European rimless wall-hung ceramic toilets with hygienic antibacterial glaze.');
INSERT INTO `category_translations` (`id`, `category_id`, `locale`, `name`, `description`) VALUES (2, 1, 'tr', 'Asma Klozetler', 'Hijyenik sırlı, kanalsız modern asma klozet ve rezervuar sistemleri.');
INSERT INTO `category_translations` (`id`, `category_id`, `locale`, `name`, `description`) VALUES (3, 1, 'cs', 'Závěsná WC', 'Prémiová bezokrajová závěsná keramická WC s hygienickou antibakteriální glazurou.');
INSERT INTO `category_translations` (`id`, `category_id`, `locale`, `name`, `description`) VALUES (4, 2, 'en', 'Luxury Bidets', 'Architectural wall-hung and floor-standing European sanitary bidets.');
